head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05314.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.TR_JOB;
scwin.vBzProcsNo;
scwin.vSecugrpID = SECUGRP_ID_EF;
scwin.gDepCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00685-명의개서대행기관
    01393-ETF구분코드
    02323 과세유형
    02635  상품종류 jackal_11.10.11
    03242 - ETF복제방법구분코드(실물,합성,Active)
    */
    var arrCid = [{
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "ETF_TP_CD",
        cnm: "cmb_ETF_TP_CD"
    }, {
        cid: "TRACE_ULY_UNIT_CD",
        cnm: "cmb_TRACE_ULY_UNIT_CD"
    }, {
        cid: "TAX_TP_CD",
        cnm: "cmb_TAX_TP_CD"
    }, {
        cid: "ETF_REPLICA_METHD_TP_CD",
        cnm: "cmb_ETF_REPLICA_METHD_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='TRANSSTK_AGNT_CD','ETF_TP_CD','TRACE_ULY_UNIT_CD','TAX_TP_CD','ETF_REPLICA_METHD_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_read_sync = function() {
    var url = "/IssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readIssueBook&inputMessageId=LISTING_ISUBOOK_SEARCH_OUT";
    url += "&SECUGRP_ID=" + scwin.vSecugrpID;
    url += "&P_KEY=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_IsuItem.DataID = encodeURI(url);
    dts_IsuItem.Reset();
    url = "/IssueBook.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readLpMbrNoIssueBook&inputMessageId=LISTING_ISUBOOK_SEARCH_OUT";
    url += "&P_KEY=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_LP.DataID = encodeURI(url);
    dts_LP.Reset();
};
scwin.fn_getDistrBasMmDd = function() {
    if (dts_IsuItem.getTotalRow() > 0) {
        for (var i = 1; i <= 12; i++) {
            if (dts_IsuItem.getCellData(1, "EARNG_DISTR_BAS_MMDD" + i) != "") {
                dts_DISTR_BAS_MMDD.insertRow();
                dts_DISTR_BAS_MMDD.setCellData(i, "EARNG_DISTR_BAS_MMDD", dts_IsuItem.getCellData(1, "EARNG_DISTR_BAS_MMDD" + i));
            }
        }
    }
};
scwin.fn_CheckForm = function() {
    return true;
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.cp.isModified(dts_IsuItem)) {
            $c.lc.fn_alertNoUpdate();
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.fn_trs(TR_JOB_UPDATE);
        }
    }
};
scwin.fn_trs = function(trsIdx) {
    if (trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/IssueBook.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=updateIssueBook");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuItem)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + scwin.vSecugrpID + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + dts_IsuItem.getCellData(1, "ISUR_CD") + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_401;
    trs_Save.Post();
};
scwin.fn_setMarketPanelEvent = function(pMarket) {
    if (pMarket == "1") {
        $c.stf.showObj(panel_ISU_ENG_SYMBL, true);
        $c.stf.showObj(panel_ISUR_SYMBL, true);
    } else if (pMarket == "2") {
        $c.stf.showObj(panel_ISU_ENG_SYMBL, false);
        $c.stf.showObj(panel_ISUR_SYMBL, false);
    }
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_SearchIsuCd) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_SearchIsuCd.focus();
        return;
    }
    scwin.fn_read_sync();
};
scwin.img_SearchIsu_onclick = function() {
    // 2009.02.26 팝업창변경.
    //fn_GetPar = fn_GetParIsuCd;
    //fn_SetPar = fn_SetParIsuCd;
    //fn_PopFindIsu(vSecugrpID);

    $c.stockSearch.JongmokSearch(txb_SearchIsuCd, txb_SearchIsuNm, scwin.vSecugrpID, js_market, "A");
    scwin.fn_read_sync();
};
scwin.img_TRSTCOM_INST_NM_onclick = function() {
    scwin.fn_SetPar = fn_SetParTrstComInstCd;
    $c.lc.fn_PopFindInstCd();
};
scwin.dts_IsuItem_OnLoadError = function() {
    $c.stf.alert_error(dts_IsuItem);
};
scwin.dts_LP_OnLoadError = function() {
    $c.stf.alert_error(dts_LP);
};
scwin.dts_DISTR_BAS_MMDD_OnLoadError = function() {
    $c.stf.alert_error(dts_DISTR_PAY);
};
scwin.dts_IsuItem_OnLoadCompleted = function(rowcount) {
    //alert('[dts_IsuItem.Status]'+dts_IsuItem.Status);
    scwin.fn_setMarketPanelEvent($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD));
    dts_DISTR_BAS_MMDD.removeAll();
    scwin.fn_getDistrBasMmDd();
};
scwin.btn_Update_onclick = function() {
    scwin.fn_update();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    // 목록 다시 조회
    scwin.fn_read_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_IdxIndCD_OnFilter = function(row) {
    //  추적기초자산 시장구분의 추적지수명(지수업종코드)목록을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_IdxIndCD.getCellData(row, "CD_ID") == scwin.gDepCd || dts_IdxIndCD.getCellData(row, "CD_ID") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.fn_setMarketPanelEvent(js_market);
    $c.elw.fn_searchCode();
    dts_DISTR_BAS_MMDD.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETF_DISTR_BAS_MMDD_INOUT";
    dts_DISTR_BAS_MMDD.reset();
};
